{
  "name": "@adayacas/loopbreaker",
  "version": "0.2.0",
  "description": "Loop breaker y guardián de alcance para agentes de OpenCode: corta bucles de herramientas y limita lo que el agente puede escribir por fase.",
  "type": "module",
  "main": "dist/src/index.js",
  "types": "dist/src/index.d.ts",
  "exports": {
    ".": "./dist/src/index.js"
  },
  "bin": {
    "loopbreaker": "dist/src/cli.js",
    "aeg": "dist/src/cli.js"
  },
  "files": [
    "dist/src",
    "README.md",
    "LICENSE"
  ],
  "scripts": {
    "build": "tsc -p tsconfig.json",
    "test": "tsc -p tsconfig.json && node --test \"dist/test/*.test.js\"",
    "prepublishOnly": "rm -rf dist && npm test && tsc -p tsconfig.build.json"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": "*"
  },
  "peerDependenciesMeta": {
    "@opencode-ai/plugin": {
      "optional": true
    }
  },
  "devDependencies": {
    "typescript": "^5.6.0",
    "@types/node": "^22.0.0"
  },
  "license": "MIT",
  "engines": {
    "node": ">=18"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "agent",
    "loop-detection",
    "circuit-breaker",
    "guardrails",
    "scope"
  ],
  "publishConfig": {
    "access": "public"
  }
}
